(5673859, 824167, 83313, '<td valign="top">Love the over-the-top obviousness!</td>', 'Love the over-the-top obviousness!', '2009-10-04 01:48:06.000000', NULL, 1),
(5673861, 824252, 83313, '<td valign="top">From this angle the X is not terribly evident, though it is there, but what a catch!</td>', 'From this angle the X is not terribly evident, though it is there, but what a catch!', '2009-10-04 01:52:50.000000', NULL, 1),
(5673863, 823796, 83313, '<td valign="top">A swastika? The shot is very good, but I have to admit this is also some uncomfortable imagery. I''m wondering what the story is behind this being scratched on the side of this canoe. Perhaps this is not as much of a paradise as it appears as first glance. Have to give this a a good vote for a well done photo that also makes one question and think about it. Hope you left some notes on this.</td>', 'A swastika? The shot is very good, but I have to admit this is also some uncomfortable imagery. I''m wondering what the story is behind this being scratched on the side of this canoe. Perhaps this is not as much of a paradise as it appears as first glance. Have to give this a a good vote for a well done photo that also makes one question and think about it. Hope you left some notes on this.', '2009-10-04 01:58:08.000000', NULL, 1),
(5673865, 824195, 83313, '<td valign="top">Wicked looking spider.</td>', 'Wicked looking spider.', '2009-10-04 01:59:03.000000', NULL, 1),
