(5674621, 824253, 12733, '<td valign="top">Nice effect, almost like spinning fire. Not so crazy about the background, though.</td>', 'Nice effect, almost like spinning fire. Not so crazy about the background, though.', '2009-10-04 18:36:40.000000', NULL, 1),
(5674622, 824204, 12733, '<td valign="top">The overall gray is perhaps fitting for the mood, but the colors of the flowers should really pop to make this an outstanding photo. It''s a delicate balance, and it may not be possible, but I''d rate this as a great idea that didn''t quite make it.</td>', 'The overall gray is perhaps fitting for the mood, but the colors of the flowers should really pop to make this an outstanding photo. It''s a delicate balance, and it may not be possible, but I''d rate this as a great idea that didn''t quite make it.', '2009-10-04 18:38:50.000000', NULL, 1),
(5674623, 824225, 12733, '<td valign="top">I''d have rated this higher if you had submitted it to missed focus. The X is difinitely there, but the picture doesn''t really come together for me.</td>', 'I''d have rated this higher if you had submitted it to missed focus. The X is difinitely there, but the picture doesn''t really come together for me.', '2009-10-04 18:40:05.000000', NULL, 1),
(5674625, 823049, 12733, '<td valign="top">A train in the distance would have made this a memorable image. As it is, it lacks a real point of focus. A lower angle, further back (possibly enough to hide the fact that one side of the X goes nowhere) and I think this could have been more dramatic.</td>', 'A train in the distance would have made this a memorable image. As it is, it lacks a real point of focus. A lower angle, further back (possibly enough to hide the fact that one side of the X goes nowhere) and I think this could have been more dramatic.', '2009-10-04 18:44:18.000000', NULL, 1),
(5674629, 824088, 12733, '<td valign="top">You''ve got a bunch of x''s. Which one marks the spot? Pretty picture, nice textures and color contrasts.</td>', 'You''ve got a bunch of x''s. Which one marks the spot? Pretty picture, nice textures and color contrasts.', '2009-10-04 18:46:28.000000', NULL, 1),
